use crate::action::Action;
use crate::entity::EntityId;
use crate::geom::{Dir, Point};
use crate::map::Map;
use crate::world::World;

pub struct Game {
    map: Map,
    world: World,
    player: EntityId,
}

impl Game {
    pub fn new() -> Game {
