        assert_eq!(map.index(Point::new(-1, 0)), None);
        assert_eq!(map.index(Point::new(0, -1)), None);
        assert_eq!(map.index(Point::new(10, 0)), None);
        assert_eq!(map.index(Point::new(0, 8)), None);
    }

