            }
            other => panic!("expected Invalid, got {other:?}"),
        }
    }

    #[test]
    fn display_is_readable() {
        let err = Defs::from_ron(&MIN.replace("hp: 5", "hp: 0")).unwrap_err();
        assert_eq!(
