        self.spawn_item(&crate::defs::builtin().items.remove(0), pos)
    }

    pub fn spawn_scroll(&mut self, pos: Point) -> EntityId {
        self.spawn_item(&crate::defs::builtin().items.remove(1), pos)
    }
}

