#[derive(Debug, Clone, Deserialize)]
pub struct MonsterDef {
    pub name: String,
    pub glyph: char,
    pub color: Rgb,
    pub hp: i32,
    pub power: i32,
    pub defense: i32,
    pub vision: i32,
