    fn play_script(game: &mut Game, steps: usize) {
        let moves = [Dir::Right, Dir::Down, Dir::Left, Dir::Up];
        for i in 0..steps {
            act(game, Action::Move(moves[i % 4]));
            if i % 5 == 0 {
                act(game, Action::Wait);
            }
        }
    }

