use rogue_core::{Action, Dir, Effect, Game, Input, Point, RunState, Tile, astar};

/// 봇의 정책. 월드를 읽기만 하고 입력 하나를 고른다 (3-2 의 몬스터 AI 와 같은 모양).
/// 입력이 필요 없는 상태(몬스터 차례, 층 생성 중, 게임오버)에서는 None
pub fn choose(game: &Game) -> Option<Input> {
    match game.state() {
        RunState::AwaitingInput => Some(on_map(game)),
        RunState::ShowInventory => Some(match heal_slot(game) {
            Some(slot) => Input::Choose(slot),
            None => Input::Cancel,
        }),
        RunState::Targeting { .. } => Some(Input::Cancel),
        RunState::MonsterTurn | RunState::Generating | RunState::GameOver { .. } => None,
    }
}

fn on_map(game: &Game) -> Input {
    let world = game.world();
    let Some(here) = world.positions.get(game.player()).map(|p| p.0) else {
        return Input::Act(Action::Wait);
    };
    let hp = game.player_hp();
    let max = world.healths.get(game.player()).map_or(1, |h| h.max);

    // 1. 체력이 바닥나면 물약
    if hp * 3 < max && heal_slot(game).is_some() {
        return Input::OpenInventory;
    }
    // 2. 보이는 몬스터 중 가장 가까운 것과 싸운다
    let nearest = world
        .monsters
        .iter()
        .filter_map(|(id, _)| world.positions.get(id))
        .map(|p| p.0)
        .filter(|&p| game.can_see(p))
        .min_by_key(|&p| p.dist2(here));
    if let Some(target) = nearest
        && let Some(step) = next_step(game, here, target)
    {
        return Input::Act(Action::Move(step));
    }
    // 3. 발밑의 아이템 줍기
    let item_here = world
        .items
        .iter()
        .any(|(id, _)| world.positions.get(id).is_some_and(|p| p.0 == here));
    if item_here {
        return Input::Act(Action::Pickup);
    }
    // 4. 계단으로
    if game.map().tile(here) == Some(Tile::Stairs) {
        return Input::Act(Action::Descend);
    }
    if let Some(stairs) = game.map().find(Tile::Stairs)
        && let Some(step) = next_step(game, here, stairs)
    {
        return Input::Act(Action::Move(step));
    }
    Input::Act(Action::Wait)
}

/// to 로 가는 최단 경로의 첫 걸음 방향
fn next_step(game: &Game, from: Point, to: Point) -> Option<Dir> {
    let path = astar(game.map(), from, to)?;
    Dir::between(from, *path.first()?)
}

/// 인벤토리에서 회복 물약이 몇 번째 칸인가
fn heal_slot(game: &Game) -> Option<usize> {
    game.inventory().position(|id| {
        matches!(
            game.world().items.get(id).map(|item| item.0),
            Some(Effect::Heal(_))
        )
    })
}

use std::sync::Arc;

use rogue_core::{Defs, Game, RunState};

use crate::bot;

const MAX_TURNS: u32 = 2000;
/// 입력 없이 도는 횟수까지 포함한 안전장치. 봇이 제자리에서 맴돌아도 끝나게 한다
const MAX_STEPS: u32 = 50_000;

#[derive(Debug, Clone, PartialEq, Eq)]
/// 한 판이 끝난 이유
pub enum Outcome {
    Died(String),
    TurnLimit,
}

#[derive(Debug, Clone, PartialEq, Eq)]
/// 한 판의 결과
pub struct RunResult {
    pub depth: u32,
    pub turns: u32,
    pub kills: u32,
    pub outcome: Outcome,
}

/// 시드 하나로 한 판을 끝까지(죽거나 상한에 닿을 때까지) 돌린다
pub fn play_one(seed: u64, defs: &Arc<Defs>) -> RunResult {
    let mut game = Game::new(seed, Arc::clone(defs));
    let mut steps = 0;
    let outcome = loop {
        if let RunState::GameOver { cause } = game.state() {
            break Outcome::Died(cause.clone()); // game 을 계속 쓰므로 이름은 복사한다
        }
        steps += 1;
        if game.turns() >= MAX_TURNS || steps >= MAX_STEPS {
            break Outcome::TurnLimit;
        }
        let input = bot::choose(&game);
        game.update(input);
        if game.state() == &RunState::Generating {
            std::thread::yield_now(); // 층 생성 스레드가 일할 틈을 준다
        }
    };
    RunResult {
        depth: game.depth(),
        turns: game.turns(),
        kills: game.kills(),
        outcome,
    }
}

use std::collections::BTreeMap;
use std::fmt;

use crate::run::{Outcome, RunResult};

/// 여러 판의 통계. 합계와 최댓값만 가져서, 어떤 순서로 더하고 합쳐도 같은 값이 된다
#[derive(Debug, Default, Clone, PartialEq, Eq)]
pub struct Stats {
    pub games: u64,
    pub total_depth: u64,
    pub max_depth: u32,
    pub total_turns: u64,
    pub total_kills: u64,
    pub turn_limit: u64,
    /// 사망 원인별 횟수. 출력 순서가 일정하도록 BTreeMap 을 쓴다
    pub deaths: BTreeMap<String, u64>,
}

impl Stats {
    pub fn add(&mut self, r: &RunResult) {
        self.games += 1;
        self.total_depth += u64::from(r.depth);
        self.max_depth = self.max_depth.max(r.depth);
        self.total_turns += u64::from(r.turns);
        self.total_kills += u64::from(r.kills);
        match &r.outcome {
            Outcome::Died(cause) => *self.deaths.entry(cause.clone()).or_default() += 1,
            Outcome::TurnLimit => self.turn_limit += 1,
        }
    }

    /// 두 통계를 하나로. map-reduce 의 reduce 단계
    pub fn merge(mut self, other: Stats) -> Stats {
        self.games += other.games;
        self.total_depth += other.total_depth;
        self.max_depth = self.max_depth.max(other.max_depth);
        self.total_turns += other.total_turns;
        self.total_kills += other.total_kills;
        self.turn_limit += other.turn_limit;
        for (cause, n) in other.deaths {
            *self.deaths.entry(cause).or_default() += n;
        }
        self
    }
}

/// 평균 표시용. 판 수가 0 이면 0
fn average(total: u64, games: u64) -> f64 {
    if games == 0 {
        return 0.0;
    }
    // 표시용 평균이라 아주 큰 수에서 정밀도가 조금 줄어도 상관없다
    total as f64 / games as f64
}

impl fmt::Display for Stats {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        writeln!(f, "games            {}", self.games)?;
        writeln!(
            f,
            "avg depth        {:.2}",
            average(self.total_depth, self.games)
        )?;
        writeln!(f, "max depth        {}", self.max_depth)?;
        writeln!(
            f,
            "avg turns        {:.1}",
            average(self.total_turns, self.games)
        )?;
        writeln!(
            f,
            "avg kills        {:.2}",
            average(self.total_kills, self.games)
        )?;
        writeln!(f, "hit turn limit   {}", self.turn_limit)?;
        for (cause, n) in &self.deaths {
            writeln!(f, "killed by {cause:<9}{n}")?;
        }
        Ok(())
    }
}

use std::sync::{Arc, Mutex};
use std::thread;

use rayon::prelude::*;
use rogue_core::Defs;

use crate::run::play_one;
use crate::stats::Stats;

/// 시드 0 부터 차례로 한 판씩
pub fn sequential(games: u64, defs: &Arc<Defs>) -> Stats {
    let mut stats = Stats::default();
    for seed in 0..games {
        stats.add(&play_one(seed, defs));
    }
    stats
}

/// scoped thread + 공유 통계 하나를 Mutex 로 보호
pub fn scoped_mutex(games: u64, defs: &Arc<Defs>, threads: u64) -> Stats {
    let shared = Arc::new(Mutex::new(Stats::default()));
    thread::scope(|scope| {
        for t in 0..threads {
            let shared = Arc::clone(&shared);
            scope.spawn(move || {
                for seed in (t..games).step_by(threads as usize) {
                    let result = play_one(seed, defs); // 잠그기 전에 계산한다
                    if let Ok(mut stats) = shared.lock() {
                        stats.add(&result);
                    }
                }
            });
        }
    });
    match Arc::try_unwrap(shared) {
        Ok(mutex) => mutex.into_inner().unwrap_or_default(),
        Err(_) => Stats::default(), // scope 가 끝났으니 다른 소유자는 없다
    }
}

/// 각 스레드가 자기 통계를 만들어 돌려주고, 마지막에 합친다 (map-reduce)
pub fn scoped_map_reduce(games: u64, defs: &Arc<Defs>, threads: u64) -> Stats {
    thread::scope(|scope| {
        let handles: Vec<_> = (0..threads)
            .map(|t| {
                scope.spawn(move || {
                    let mut stats = Stats::default();
                    for seed in (t..games).step_by(threads as usize) {
                        stats.add(&play_one(seed, defs));
                    }
                    stats
                })
            })
            .collect();
        handles
            .into_iter()
            .filter_map(|h| h.join().ok())
            .fold(Stats::default(), Stats::merge)
    })
}

/// rayon. 순차 버전과 거의 같은 모양이다
pub fn parallel(games: u64, defs: &Arc<Defs>) -> Stats {
    (0..games)
        .into_par_iter()
        .map(|seed| {
            let mut stats = Stats::default();
            stats.add(&play_one(seed, defs));
            stats
        })
        .reduce(Stats::default, Stats::merge)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn defs() -> Arc<Defs> {
        Arc::new(Defs::load("../data/defs.ron").expect("run tests from the rogue-sim folder"))
    }

    #[test]
    fn every_method_gives_identical_statistics() {
        let defs = defs();
        let n = 40;
        let baseline = sequential(n, &defs);
        assert_eq!(baseline.games, n);
        for threads in [1, 2, 3, 7] {
            assert_eq!(
                scoped_mutex(n, &defs, threads),
                baseline,
                "mutex x{threads}"
            );
            assert_eq!(
                scoped_map_reduce(n, &defs, threads),
                baseline,
                "map-reduce x{threads}"
            );
        }
        assert_eq!(parallel(n, &defs), baseline, "rayon");
    }

    #[test]
    fn same_seed_same_result() {
        let defs = defs();
        assert_eq!(play_one(3, &defs), play_one(3, &defs));
    }

    #[test]
    fn the_bot_gets_somewhere() {
        let defs = defs();
        let stats = sequential(30, &defs);
        assert!(stats.total_depth > 0, "bot never left the first floor");
    }
}

