        let old = text.replacen(&format!("version:{SAVE_VERSION}"), "version:99", 1);
        assert_ne!(old, text);
        match Game::from_save_string(&old, crate::defs::builtin_arc()) {
            Err(DataError::Version { found, expected }) => {
                assert_eq!((found, expected), (99, 1));
